<script lang="ts">
  import AcademicEmptyState from '$lib/components/academic/AcademicEmptyState.svelte'; import AcademicErrorState from '$lib/components/academic/AcademicErrorState.svelte'; import SourceBadge from '$lib/components/academic/SourceBadge.svelte'; import PageHeader from '$lib/components/shell/PageHeader.svelte'; let { data } = $props();
  const dateFormatter = new Intl.DateTimeFormat('en-PH', { month: 'short', day: 'numeric', year: 'numeric' }); const formatDate = (value: string) => dateFormatter.format(new Date(`${value}T00:00:00+08:00`));
</script>
<svelte:head><title>Academic Calendar · IMS Academic Hub</title></svelte:head>
<div class="mx-auto grid w-full max-w-[1180px] gap-7 px-4 py-7 sm:px-6 sm:py-9"><PageHeader eyebrow="Academic calendar" title="Important dates, with their source attached." description="An information layer over published dates—not a replacement for the Registrar’s authoritative calendar." />
